  const [historySearch, setHistorySearch] = useState("");
  const [historySource, setHistorySource] = useState<"ALL"|"PLANNED"|"FREE"|"ATTENDANCE"|"IMPORTED">("ALL");
  const [historyPeriod, setHistoryPeriod] = useState<"ALL"|"30"|"90"|"YEAR">("ALL");
  const [workoutsOnly, setWorkoutsOnly] = useState(false);
  const [showGoogleEventForm, setShowGoogleEventForm] = useState(false);
  const [showFinancePin, setShowFinancePin] = useState(false);
  const [financePin, setFinancePin] = useState("");
  const [financePinError, setFinancePinError] = useState("");
  const [notes, setNotes] = useState<DmpNote[]>([]);
  const [newNoteTitle, setNewNoteTitle] = useState("");
  const [newNote, setNewNote] = useState("");
  const [newNoteDate, setNewNoteDate] = useState("");
  const [newNoteTime, setNewNoteTime] = useState("");
  const [newNotePriority, setNewNotePriority] = useState(4);
  const [notesBusy, setNotesBusy] = useState(false);
  const [notesError, setNotesError] = useState("");
  const [removedNote, setRemovedNote] = useState<{note:DmpNote;index:number}|null>(null);
  const [editingNoteId, setEditingNoteId] = useState<string|null>(null);
  const [editingNoteTitle, setEditingNoteTitle] = useState("");
  const [editingNoteText, setEditingNoteText] = useState("");
  const [editingNoteDate, setEditingNoteDate] = useState("");
  const [editingNoteTime, setEditingNoteTime] = useState("");
  const [editingNotePriority, setEditingNotePriority] = useState(4);
  const [kidsLessonRequest,setKidsLessonRequest]=useState<KidsLessonOpenRequest|null>(null);
  const [kidsStudentRequest,setKidsStudentRequest]=useState<string|null>(null);
  const [kidsEntryKey,setKidsEntryKey]=useState(0);
  const [homeMonthKidsCount,setHomeMonthKidsCount]=useState<number|null>(null);
  const [homeMonthKidsRows,setHomeMonthKidsRows]=useState<CalendarEvent[]>([]);
  const [homeKidsCalendarEvents,setHomeKidsCalendarEvents]=useState<CalendarEvent[]>([]);
  const [showMobileActions,setShowMobileActions]=useState(false);
  const [todayPerformanceActivities,setTodayPerformanceActivities]=useState<PerformanceActivity[]>([]);
  const [homePerformanceActivities,setHomePerformanceActivities]=useState<PerformanceActivity[]>([]);
  const [spotifyState,setSpotifyState]=useState<{
    connected:boolean;
    active?:boolean;
    isPlaying?:boolean;
    track?:{name:string;artist:string;image:string}|null;
    progressMs?:number;
    durationMs?:number;
  }>({connected:false});
  const [spotifyBusy,setSpotifyBusy]=useState(false);
  const [spotifyProgressMs,setSpotifyProgressMs]=useState(0);
  const [selectedPerformanceActivityId,setSelectedPerformanceActivityId]=useState<string|null>(null);
  const deepLinkHandled = useRef(false);
  const sessionReturnView = useRef<View>("student");
  const browserHistoryReady = useRef(false);
  const browserBackRestoring = useRef(false);
  useEffect(() => {
    const nativeFetch = window.fetch.bind(window);
    let redirecting = false;
    const guardedFetch: typeof window.fetch = async (...args) => {
      const response = await nativeFetch(...args);
      if (!redirecting && response.status === 401) {
        const payload = await response.clone().json().catch(() => null);
        if (payload?.message === "Sessão inválida. Entre novamente no DMP.") {
          redirecting = true;
          window.location.replace("/login");
        }
      }
      return response;
    };
    window.fetch = guardedFetch;
    return () => {
      if (window.fetch === guardedFetch) window.fetch = nativeFetch;
    };
  }, []);

  useEffect(()=>{
    let active=true;
    const params=new URLSearchParams(window.location.search);
    const saved=restoredNavigation(window.history.state?.dmpFinancePending?{...window.history.state,view:"finance"}:window.history.state,params.get("home")==="1");
    if(params.get("home")==="1")window.history.replaceState(null,"","/app");
    async function restore(){
      if(saved){
        const q=window.history.state?.dmpQueries||{};
        if(typeof q.search==="string")setSearch(q.search);
        if(typeof q.historySearch==="string")setHistorySearch(q.historySearch);
        if(["ACTIVE","ARCHIVED"].includes(q.studentFilter))setStudentFilter(q.studentFilter);
        if(["ALL","PLANNED","FREE","ATTENDANCE","IMPORTED"].includes(q.historySource))setHistorySource(q.historySource);
        if(["ALL","30","90","YEAR"].includes(q.historyPeriod))setHistoryPeriod(q.historyPeriod);
        if(["day","week","month","year","list"].includes(q.calendarRange))setCalendarRange(q.calendarRange);
        if(/^\d{4}-\d{2}-\d{2}$/.test(q.calendarAnchor||""))setCalendarAnchor(q.calendarAnchor);
        setSelectedStudentId(saved.selectedStudentId);setTab(saved.tab as StudentTab);
        if(saved.view==="finance"){
          try{const r=await fetch("/api/finance/pin",{cache:"no-store"});const result=await r.json();
            if(!active)return;
            if(r.ok&&result.unlocked){sessionStorage.setItem(FINANCE_UNLOCK_KEY,String(result.until));setView("finance");}
            else {sessionStorage.removeItem(FINANCE_UNLOCK_KEY);setShowFinancePin(true);}
          }catch{if(active)setShowFinancePin(true);}
        }else setView(saved.view as View);
      }
      if(active)setNavigationReady(true);
    }
    void restore();return()=>{active=false;};
  },[]);
  useEffect(()=>{
    if(navigationReady&&studentsLoaded&&view==="student"&&!students.some(s=>s.id===selectedStudentId)){setSelectedStudentId(null);setView("today");}
  },[navigationReady,studentsLoaded,students,view,selectedStudentId]);


  // Histórico real de navegação: cada tela do DMP vira uma etapa do botão/gesto Voltar.
  useEffect(() => {
    if(!navigationReady)return;
    const snapshot={dmpNav:true,view,tab,selectedStudentId,dmpFinancePending:showFinancePin,dmpQueries:{search,studentFilter,historySearch,historySource,historyPeriod,calendarRange,calendarAnchor}};
    if(!browserHistoryReady.current){
      window.history.replaceState({...window.history.state,...snapshot},"",window.location.href);
      browserHistoryReady.current=true;
      return;
    }
    if(browserBackRestoring.current){
      browserBackRestoring.current=false;
      return;
    }
    const state=window.history.state;
    const same=state?.dmpNav&&state.view===view&&state.tab===tab&&(state.selectedStudentId||null)===(selectedStudentId||null);
    if(!same)window.history.pushState({...state,...snapshot},"",window.location.href);
    else window.history.replaceState({...state,...snapshot},"",window.location.href);
  },[view,tab,selectedStudentId,navigationReady,search,studentFilter,historySearch,historySource,historyPeriod,calendarRange,calendarAnchor,showFinancePin]);

  useEffect(() => {
    const restoreCurrent=()=>window.history.pushState({...window.history.state,dmpNav:true,view,tab,selectedStudentId},"",window.location.href);
    const onPopState=(event:PopStateEvent)=>{
      if(showFinancePin){setShowFinancePin(false);restoreCurrent();return;}
      if(showStudentForm){setShowStudentForm(false);restoreCurrent();return;}
      if(showEditStudentForm){setShowEditStudentForm(false);restoreCurrent();return;}
      if(showAssessmentForm){setShowAssessmentForm(false);restoreCurrent();return;}
      if(showGoogleEventForm){setShowGoogleEventForm(false);restoreCurrent();return;}
      if(view==="workout-editor"&&!confirm("Voltar sem salvar? Alterações feitas nesta montagem podem ser perdidas.")){restoreCurrent();return;}
      const state=event.state;
      if(state?.dmpNav){
        browserBackRestoring.current=true;
        setSelectedStudentId(state.selectedStudentId||null);
        setTab((state.tab||"summary") as StudentTab);
        if(state.view==="finance"){setView("today");void navigateMain("finance");}else {financeAttempt.current++;setView((state.view||"today") as View);}
        return;
      }
      // Fallback: sem histórico interno válido, volta para Hoje em vez de saltar de forma imprevisível.
      if(view!=="today"){
        browserBackRestoring.current=true;
        setSelectedStudentId(null);
        setTab("summary");
        setView("today");
        window.history.pushState({dmpNav:true,view:"today",tab:"summary",selectedStudentId:null},"",window.location.href);
      }
    };
    window.addEventListener("popstate",onPopState);
    return()=>window.removeEventListener("popstate",onPopState);
  },[view,tab,selectedStudentId,showFinancePin,showStudentForm,showEditStudentForm,showAssessmentForm,showGoogleEventForm]);


  useEffect(()=>{
  let cancelled=false;

  fetch("/api/workout-templates",{cache:"no-store"})
    .then(async response=>{
      const result=await response.json();

      if(!response.ok||!result.ok){
        throw new Error(
          result.error||
          "Falha ao carregar biblioteca de treinos."
        );
      }

      if(cancelled)return;

      if(result.updatedAt){
        window.sessionStorage.setItem(
          "dmp_workout_templates_cloud_updated_at",
          String(result.updatedAt)
        );
      }else{
        window.sessionStorage.removeItem(
          "dmp_workout_templates_cloud_updated_at"
        );
      }

      setPersonalWorkoutTemplates(
        Array.isArray(result.data)
          ?result.data
          :[]
      );

      setWorkoutTemplatesLoaded(true);
    })
    .catch(error=>{
      console.error(
        "Erro ao carregar biblioteca de treinos:",
        error
      );
    });

  return()=>{cancelled=true;};
},[]);

  useEffect(()=>{
  if(!workoutTemplatesLoaded)return;

  const timer=window.setTimeout(()=>{
    const expected=
      window.sessionStorage.getItem(
        "dmp_workout_templates_cloud_updated_at"
      )||"";

    const headers:Record<string,string>={
      "Content-Type":"application/json"
    };

    if(expected){
      headers["X-DMP-Expected-Updated-At"]=expected;
    }

    void fetch("/api/workout-templates",{
      method:"PUT",
      headers,
      body:JSON.stringify(personalWorkoutTemplates)
    })
      .then(async response=>{
        const result=
          await response.json().catch(()=>({}));

        if(response.status===409){
          alert(
            "A Biblioteca de Treinos foi alterada em outra aba ou dispositivo. Esta gravação foi bloqueada para proteger os dados. Atualize a página antes de continuar."
          );
          return;
        }

        if(!response.ok||!result.ok){
          throw new Error(
            result.error||
            "Falha ao salvar biblioteca de treinos."
          );
        }

        if(result.updatedAt){
          window.sessionStorage.setItem(
            "dmp_workout_templates_cloud_updated_at",
            String(result.updatedAt)
          );
        }
      })
      .catch(error=>{
        console.error(
          "Erro ao salvar biblioteca de treinos:",
          error
        );
      });
  },350);

  return()=>window.clearTimeout(timer);
},[
  personalWorkoutTemplates,
  workoutTemplatesLoaded
]);

  useEffect(() => setStudents(loadStudents(importedStudents2026)), []);
useEffect(() => {
  let cancelled = false;

  async function loadStudentsFromCloud() {
    const localStudents = loadStudents(importedStudents2026);

    try {
      const response = await fetch("/api/data", { cache: "no-store" });

      if (!response.ok) {
        throw new Error("Falha ao carregar dados da nuvem");
      }

      const result = await response.json();

      if (!Array.isArray(result.data)) {
        throw new Error("Dados da nuvem inválidos");
      }

      if (cancelled) return;

      setStudents(result.data as Student[]);
      saveStudents(result.data as Student[]);
      setCloudWritable(true);
    } catch (error) {
      console.error("Nuvem indisponível; usando backup local:", error);

      if (cancelled) return;

      setStudents(localStudents);
      setCloudWritable(false);
    } finally {
      if (!cancelled) {
        setStudentsLoaded(true);
      }
    }
  }

  void loadStudentsFromCloud();

  return () => {
    cancelled = true;
  };
}, []);

useEffect(() => {
  if (!studentsLoaded || today() !== "2026-09-23") return;

  // Recuperação pontual das duas ausências de hoje que foram perdidas pelo
  // antigo fluxo automático de restauração. É idempotente e só roda nesta data.
  const repairs = [
    {name:"Poeira",start:"2026-09-23T07:30:00-03:00",end:"2026-09-23T08:30:00-03:00"},
    {name:"Pedro Eroles",start:"2026-09-23T09:00:00-03:00",end:"2026-09-23T10:00:00-03:00"}
  ];

  setStudents(current=>{
    let changed=false;
    const next=current.map(student=>{
      const repair=repairs.find(item=>normalizeName(item.name)===normalizeName(student.name));
      if(!repair)return student;

      const existingIndex=student.sessions.findIndex(session=>session.source==="ABSENCE"&&session.date==="2026-09-23");
      const calendarEvent:CalendarEvent={
        id:`dmp-recovered-absence:2026-09-23:${student.id}`,
        summary:calendarStudentDisplayName(student),
        description:"Ausência recuperada pelo DMP.",
        start:repair.start,
        end:repair.end,
        allDay:false,
        matchedStudentId:student.id,
        matchedStudentIds:[student.id]
      };

      if(existingIndex>=0){
        const existing=student.sessions[existingIndex];
        if(existing.calendarEvent)return student;
        const sessions=[...student.sessions];
        sessions[existingIndex]={...existing,calendarEvent};
        changed=true;
        return {...student,sessions};
      }

      const absence:Session={
        id:crypto.randomUUID(),
        date:"2026-09-23",
        workoutName:"Ausência",
        notes:"Ausência informada.",
        completedExercises:[],
        source:"ABSENCE",
        finishedAt:new Date().toISOString(),
        calendarEvent
      };
      changed=true;
      return {...student,sessions:[absence,...student.sessions]};
    });
    return changed?next:current;
  });
},[studentsLoaded]);

useEffect(() => {
  if (!studentsLoaded) return;

  saveStudents(students);

  if (!cloudWritable) return;

  const timer = window.setTimeout(() => {
    void fetch("/api/data", {
      method: "PUT",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify(students),
    }).catch(error => {
      console.error("Erro ao salvar na nuvem:", error);
    });
  }, 300);

  return () => window.clearTimeout(timer);
}, [students, studentsLoaded, cloudWritable]);

useEffect(() => {
  if (!studentsLoaded || deepLinkHandled.current) return;
  deepLinkHandled.current = true;
  const params = new URLSearchParams(window.location.search);
  const mode=params.get("mode");
  const studentId = params.get("student");
  const student = students.find(item => item.id === studentId);
  if(!student)return;

  if(mode==="planned-session"){
    const workoutId = params.get("workout");
    const workout = student.workouts.find(item => item.id === workoutId && item.active !== false);
    if(!workout)return;
    setSelectedStudentId(student.id);
    setSelectedWorkoutId(workout.id);
    setView("planned-session");
    return;
  }

  if(mode==="historical-session"){
    const sessionId=params.get("session");
    const session=student.sessions.find(item=>item.id===sessionId);
    if(!session||!session.completedExercises.length)return;
    setSelectedStudentId(student.id);
    setHistoricalSessionPreview({...session,completedExercises:session.completedExercises.map(exercise=>({...exercise}))});
    setView("historical-workout");
  }
}, [studentsLoaded, students]);

useEffect(() => {
  const channel = new BroadcastChannel(STUDENTS_CHANNEL);
  channel.onmessage = async () => {
    try {
      const response = await fetch("/api/data", {cache:"no-store"});
      const result = await response.json();
      if (response.ok && Array.isArray(result.data)) {
        setStudents(result.data as Student[]);
        saveStudents(result.data as Student[]);
      }
    } catch {}
  };
  return () => channel.close();
}, []);
useEffect(() => {
  let cancelled=false;

  const refresh=async()=>{
    try{
      const response=await fetch("/api/notes",{cache:"no-store"});
      const result=await response.json().catch(()=>({}));
      if(!response.ok||!result.ok){
        throw new Error(result.error||"Falha ao carregar recados do Todoist.");
      }
      if(cancelled)return;
      setNotes(Array.isArray(result.data)?result.data:[]);
      setNotesError(String(result.google?.warning||""));
    }catch(error){
      if(cancelled)return;
      console.error("Erro ao carregar recados do Todoist:",error);
      setNotesError(error instanceof Error?error.message:"Falha ao carregar recados do Todoist.");
    }
  };

  const onFocus=()=>{void refresh();};
  const onVisibility=()=>{
    if(document.visibilityState==="visible")void refresh();
  };

  void refresh();
  window.addEventListener("focus",onFocus);
  document.addEventListener("visibilitychange",onVisibility);
  const timer=window.setInterval(()=>{
    if(document.visibilityState==="visible")void refresh();
  },30000);

  return()=>{
    cancelled=true;
    window.removeEventListener("focus",onFocus);
    document.removeEventListener("visibilitychange",onVisibility);
    window.clearInterval(timer);
  };
},[]);

useEffect(()=>{
  if(view!=="today")return;
  let cancelled=false;

  const loadHomePerformance=async()=>{
    try{
      const response=await fetch("/api/performance",{cache:"no-store"});
      const result=await response.json();
      const activities:PerformanceActivity[]=result?.data?.activities||[];

      if(!cancelled){
        setHomePerformanceActivities(activities);
        setTodayPerformanceActivities(
          activities
            .filter(activity=>activity.date===today())
            .sort((a,b)=>(b.createdAt||"").localeCompare(a.createdAt||""))
        );
      }
    }catch{
      if(!cancelled){setTodayPerformanceActivities([]);setHomePerformanceActivities([]);}
    }
  };

  void loadHomePerformance();
  return()=>{cancelled=true;};
},[view]);

useEffect(()=>{
  if(view==="student"){
    window.requestAnimationFrame(()=>{
      window.scrollTo({top:0,left:0,behavior:"auto"});
    });
  }
},[view,selectedStudentId]);

useEffect(()=>{
  if(view!=="today")return;
  let cancelled=false;
  let spotifyUnauthorized=false;
  const loadSpotify=async()=>{
    if(spotifyUnauthorized)return;
    try{
