    setCalendarLoading(true);
    try {
      const monthStart=`${today().slice(0,7)}-01`; const response=await fetch(`/api/google/calendar?date=${monthStart}&days=45`,{cache:"no-store"});
      if (!response.ok) {
        const errorData=await response.json().catch(()=>({}));
